<?php require_once "../config/database.php";require_once "../includes/auth.php";require_role("admin");$rows=$conn->query("SELECT category,COUNT(*) total FROM complaints GROUP BY category ORDER BY total DESC");$st=$conn->query("SELECT status,COUNT(*) total FROM complaints GROUP BY status");include "../includes/header.php";?><h2>Reports</h2><div class="grid"><div class="card"><h3>By Category</h3><?php while($r=$rows->fetch_assoc()):?><p><?=e($r["category"])?><b style="float:right"><?=$r["total"]?></b></p><?php endwhile;?></div><div class="card"><h3>Status</h3><?php while($r=$st->fetch_assoc()):?><p><?=e($r["status"])?><b style="float:right"><?=$r["total"]?></b></p><?php endwhile;?></div></div><?php include "../includes/footer.php";?>